import xarray as xr
import numpy as np
import pandas as pd
import pytest

def test_rolling_mean_keepdims():
    da = xr.DataArray(np.random.rand(10), dims="x")
    rolling = da.rolling(x=3)
    try:
        rolling.mean(keepdims=True)
    except TypeError:
        return # Success
    except Exception as e:
        pytest.fail(f"Expected TypeError, got {type(e).__name__}: {e}")
    pytest.fail("Expected TypeError when passing keepdims to rolling.mean")

def test_groupby_mean_keepdims():
    da = xr.DataArray(np.random.rand(10), dims="x")
    coords = np.arange(10) % 2
    da = da.assign_coords(group=coords)
    groupby = da.groupby("group")
    try:
        groupby.mean(keepdims=True)
    except TypeError:
        return # Success
    except Exception as e:
        pytest.fail(f"Expected TypeError, got {type(e).__name__}: {e}")
    pytest.fail("Expected TypeError when passing keepdims to groupby.mean")

if __name__ == "__main__":
    try:
        test_rolling_mean_keepdims()
        print("Rolling mean keepdims test passed (raised TypeError)")
    except Exception as e:
        print(f"Rolling mean keepdims test failed: {e}")
        exit(1)

    try:
        test_groupby_mean_keepdims()
        print("Groupby mean keepdims test passed (raised TypeError)")
    except Exception as e:
        print(f"Groupby mean keepdims test failed: {e}")
        exit(1)
